// §1.11 step 6 -- turn four independent readings into one budget percentage.
//
// Two budgets are tracked because they fail differently:
//   * MODEL SPEND is money, accrues monthly, and is compared against
//     MONTHLY_MODEL_BUDGET_USD.
//   * PROVIDER QUOTA is a daily allowance that RESETS. Spending 95% of it does
//     not cost anything; it means the next few requests return nothing at all.
// The headline percent is the WORSE of the two, because either one hitting
// 100% stops the product working, and averaging them would hide that.

function first(nodeName) {
  try {
    const items = $(nodeName).all();
    return items && items.length ? items[0].json : {};
  } catch (e) {
    // A failed read is reported as missing, never as zero: "we spent $0" and
    // "we could not find out what we spent" must not look identical.
    return { _unavailable: true, _error: String(e.message || e) };
  }
}

const usage   = first('Read Model Usage');
const quota   = first('Read Provider Quota Usage');
const errors  = first('Read n8n Error Rate and Latency');
const health  = first('Read Disk_Database_Backup Health');

// NEW DECISION: the two budget constants live HERE, in the workflow, not in
// $env. n8n blocks environment access inside Code nodes by default, and the
// unblock switch (N8N_BLOCK_ENV_ACCESS_IN_NODE=false) is all-or-nothing -- it
// would expose the whole .env, including the Anthropic key, the YouTube key and
// the OAuth token encryption key, to every workflow in the instance. Trading
// that for two numbers that are neither secret nor volatile is a bad deal, and
// SEC-101 exists to prevent exactly this shape of leak.
//
// Change them here (and re-export the workflow JSON, which is the versioned
// record). YOUTUBE_DAILY_QUOTA_UNITS mirrors Google's default project quota;
// raise it only if Google actually granted an increase.
const MONTHLY_MODEL_BUDGET_USD = 20;
const YOUTUBE_DAILY_QUOTA_UNITS = 10000;

const monthlyBudget = MONTHLY_MODEL_BUDGET_USD;
const dailyQuota    = YOUTUBE_DAILY_QUOTA_UNITS;

const costMonth = Number(usage.cost_month_usd || 0);
const modelPercent = monthlyBudget > 0
  ? (costMonth / monthlyBudget) * 100
  : null;

const providers = Array.isArray(quota.providers) ? quota.providers : [];
const youtube = providers.find((p) => p.provider === 'youtube') || {};
const units24h = Number(youtube.units_24h || 0);
const quotaPercent = dailyQuota > 0 ? (units24h / dailyQuota) * 100 : null;

const candidates = [modelPercent, quotaPercent].filter((v) => v !== null);
const budgetPercent = candidates.length ? Math.max(...candidates) : null;

const requests = Number(errors.requests_24h || 0);

return [{
  json: {
    budget_percent: budgetPercent === null ? null : Math.round(budgetPercent * 100) / 100,
    drivers: {
      model_spend_percent: modelPercent === null ? null : Math.round(modelPercent * 100) / 100,
      provider_quota_percent: quotaPercent === null ? null : Math.round(quotaPercent * 100) / 100,
      // Which of the two produced the headline, so an alert is actionable
      // rather than just alarming.
      binding_constraint: budgetPercent === null
        ? 'unknown'
        : (modelPercent !== null && modelPercent >= (quotaPercent || 0) ? 'model_spend' : 'provider_quota'),
    },
    model_usage: {
      unavailable: usage._unavailable === true,
      cost_24h_usd: Number(usage.cost_24h_usd || 0),
      cost_month_usd: costMonth,
      monthly_budget_usd: monthlyBudget,
      calls_24h: Number(usage.calls_24h || 0),
      tokens_24h: Number(usage.tokens_24h || 0),
    },
    provider_quota: {
      unavailable: quota._unavailable === true,
      daily_quota_units: dailyQuota,
      providers: providers,
      // Stated so nobody reads units_utc_today as Google's own counter.
      caveat: 'UTC day; YouTube resets at midnight US/Pacific',
    },
    reliability: {
      unavailable: errors._unavailable === true,
      requests_24h: requests,
      non_completed_24h: Number(errors.non_completed_24h || 0),
      avg_latency_ms: Number(errors.avg_latency_ms || 0),
      p95_latency_ms: Number(errors.p95_latency_ms || 0),
      fallback_used_24h: Number(errors.fallback_used_24h || 0),
      // Not called "error_rate": only successful requests are recorded today.
      completeness: 'only completed requests are recorded; refusals and upstream failures are not counted',
    },
    health: {
      unavailable: health._unavailable === true,
      database_bytes: Number(health.database_bytes || 0),
      database_mb: Math.round((Number(health.database_bytes || 0) / 1048576) * 100) / 100,
      audio_jobs_rows: Number(health.audio_jobs_rows || 0),
      expired_guest_sessions: Number(health.expired_guest_sessions || 0),
      knowledge_chunks: Number(health.knowledge_chunks || 0),
      chunks_missing_embeddings: Number(health.chunks_missing_embeddings || 0),
      exports_24h: Number(health.exports_24h || 0),
      backup: {
        configured: false,
        detail: 'DEP-007 (encrypted off-host backup + restore drill) is not implemented',
      },
    },
  },
}];

// §1.11 step 7 -- the 50/75/90/95 rules, and step 7's hard instruction:
// "At 95% of the monthly budget, disable optional expensive paths, not the
// deterministic core."
//
// The thresholds are named rather than inlined at the comparison so the report
// and the alert cannot drift apart from the rule that produced them.
const THRESHOLDS = [
  { at: 95, level: 'emergency' },
  { at: 90, level: 'critical' },
  { at: 75, level: 'warning' },
  { at: 50, level: 'notice' },
];

const data = $input.first().json;
const percent = data.budget_percent;

let level = 'ok';
if (percent === null || percent === undefined) {
  // Unknown is NOT ok. A monitoring workflow that cannot read its own inputs
  // must say so, or a silent outage reads exactly like a quiet day.
  level = 'unknown';
} else {
  for (const t of THRESHOLDS) {
    if (percent >= t.at) { level = t.level; break; }
  }
}

// What to actually do, per level. These are recommendations, not automatic
// mutations: n8n does not rewrite the environment, and a workflow that silently
// turned features off would violate the plan's own "never switch silently" rule
// (Section 2.3). ENABLE_EXPENSIVE_MODEL_PATHS and ENABLE_CLAP already exist as
// flags for exactly this moment.
const ACTIONS = {
  ok: [],
  unknown: ['investigate why the monitoring reads returned nothing'],
  notice: ['no action; half the budget is a normal mid-period position'],
  warning: ['review the cost driver named in drivers.binding_constraint'],
  critical: [
    'reduce MAX_SEARCH_INTENTS (each intent costs 100 quota units)',
    'confirm the provider result cache is being hit',
  ],
  emergency: [
    'set ENABLE_EXPENSIVE_MODEL_PATHS=false -- optional expensive paths only',
    'set ENABLE_CLAP=false',
    'DO NOT disable the deterministic core: retrieval, ranking and sequencing stay on',
  ],
};

const alertRequired = level !== 'ok' && level !== 'notice';

return [{
  json: {
    ...data,
    alert_level: level,
    alert_required: alertRequired,
    recommended_actions: ACTIONS[level] || [],
    thresholds: THRESHOLDS,
    summary_date: new Date().toISOString().slice(0, 10),
  },
}];

