={{ (() => {
  const d = $('Apply 50_75_90_95 Percent Rules').item.json;
  return [
    JSON.stringify({
      model_usage: d.model_usage,
      provider_quota: d.provider_quota,
      reliability: d.reliability,
      health: d.health,
      drivers: d.drivers,
      recommended_actions: d.recommended_actions,
      thresholds: d.thresholds,
    }),
    (d.budget_percent === null || d.budget_percent === undefined ? 0 : d.budget_percent),
    d.alert_level,
    // True only if this execution came through the alert branch. `$runIndex`
    // is not usable here; the branch identity is, because the false branch
    // reaches this node without the alert node ever running.
    (() => { try { return $('Send Alert if Needed').all().length > 0; } catch (e) { return false; } })(),
  ];
})() }}
